import json
import urllib.parse
from http.server import HTTPServer, BaseHTTPRequestHandler
import threading
import os

class BookServer(BaseHTTPRequestHandler):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.books = {}  # id -> book dict
        self.next_id = 1

    def do_POST(self):
        if self.path == '/books':
            content_length = int(self.headers.get('Content-Length', 0))
            if content_length == 0:
                self.send_error(400, 'Empty body')
                return
            body = self.rfile.read(content_length).decode('utf-8')
            try:
                data = json.loads(body)
            except json.JSONDecodeError:
                self.send_error(400, 'Invalid JSON')
                return

            # Validate required fields
            required = {'title', 'author', 'isbn'}
            missing = required - set(data.keys())
            if missing:
                self.send_error(400, f'Missing required field(s): {", ".join(missing)}')
                return
            if not data['title'] or not data['author'] or not data['isbn']:
                self.send_error(400, 'Empty title, author, or isbn')
                return

            book = {
                'id': self.next_id,
                'title': data['title'],
                'author': data['author'],
                'isbn': data['isbn'],
                'synopsis': data.get('synopsis', '')
            }
            self.books[self.next_id] = book
            self.next_id += 1
            self.send_response(201)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps(book).encode())
        else:
            self.send_error(404, 'Not found')

    def do_GET(self):
        if self.path == '/books':
            # Handle filtering and sorting
